import{_ as a,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"4、【蒙】 坎下艮上","description":"周易阐真 - 4、【蒙】 坎下艮上","frontmatter":{"title":"4、【蒙】 坎下艮上","description":"周易阐真 - 4、【蒙】 坎下艮上"},"headers":[],"relativePath":"zh/classics/chanzhen/005.md","filePath":"zh/classics/chanzhen/005.md"}'),s={name:"zh/classics/chanzhen/005.md"};function n(c,p,i,o,h,l){return t(),e("div",null,[...p[0]||(p[0]=[r('<blockquote><p>彖曰：山下有险，险而止，蒙。蒙亨，以亨行时中也。匪我求童蒙，童蒙求我，志应也。初筮告，以刚中也。再三渎，渎则不告，渎蒙也。蒙以养正，圣功也。</p></blockquote><h1 id="_4、【蒙】-坎下艮上" tabindex="-1">4、【蒙】 坎下艮上 <a class="header-anchor" href="#_4、【蒙】-坎下艮上" aria-label="Permalink to “4、【蒙】 坎下艮上”">​</a></h1><p>初六：发蒙，利用刑人，用说桎梏，以往吝。</p><p>九二：包蒙吉。纳妇吉，子克家。</p><p>六三：勿用取女。见金夫，不有躬，无攸利。</p><p>六四：困蒙，吝。</p><p>六五：童蒙，吉。</p><p>上九：击蒙，不利为寇，利御寇。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：山下出泉，蒙。君子以果行育德。</p><p>蒙者，无识无知，修养之义。上艮山，下坎水，坎言泉而不言水者，山下之泉即是水。山下出泉，泉得山养，为有本之水，源远流长，通行无阻，蒙之象也。</p><p>君子有见于此，知修道者欲行德于外，先须养德于内，若不养而即行，则行而无本，中无主宰，反伤其德。以是效泉之出山，无阻而果行；法山之养泉，敦厚而育德也。坎中一阳，系天一所生，乃生物之祖气，所谓天德者是也。此德隐于后天之中，一切常人，顺其后天，弃其先天，多不知育养修持，渐次消耗，自伤性命。若有醒悟者，截然放下，育于内而行于外，育以济行，行以验育，内外兼修，育固养，行亦养，可以复全天德，不为后天阴气所伤矣。但育德须要无一德之不育，果行须要无一行之不果。育德须要育到如山之不动不摇，方是育之至；果行须要果到如泉之昼夜流通，方是果之至。行果德育，尽性了命，浑然天理，不识不知，顺帝之则，此蒙之所以贵也。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>渎，音独。说，音脱。桎，音质。梏，古毒反。</p><p>蒙者，昏昧无知之义。卦体上艮，二阴进于一阳之下；下坎，一阳陷于二阴之中，皆有阴伤其阳之象，故谓蒙。又卦德险在止中，有险而能止，兼有止蒙之义。此运阴符下手之卦，承上坤卦而来。坤者，行顺道也。运阴符者，运其不顺之阴，而归于顺也。</p><p>人自先天阳极，后天阴生，元神昧而识神用事，陷真认假，误用聪明，巧智百出，外虽明而内实暗，此蒙之所由来也。一入于蒙，性乱命摇，一日千生万死，莫知底止，险之极矣。若知有险而能止之，黜聪毁智，如愚如讷，外虽无知，内实有知，由假蒙而归真蒙，是蒙中反有亨道矣。</p><p>蒙之亨者，莫过于童。蒙童之蒙，不识不知，顺帝之则，寂然不动，感而遂通，一举一动，皆从本性中流出，俨然圣贤身分，天人面目。行蒙道者，必归于童之蒙，方是返本还元之蒙。然此返本还元之蒙，匪我求童蒙，童蒙求我也。</p><p>匪我求童蒙者，非由勉强，不着于色也。童蒙求我者，出于自然，不落于空也。不着于色，不落于空，非色非空，既非求真，又不除假，常静常应，常应常静，不蒙而似蒙，蒙而实不蒙，外物不得而入，内念不得而生，不求真而真即在是。但此非色非空之道，有养蒙发蒙二法，不可不知。当其阴阳混成，天真未伤，客气未入，蒙属于真，如初筮著策未分之时，必先告命，须当虚静诚敬，以行无为之道。及其阴阳已判，天真有亏，客气潜入，蒙归于假，如蓍策再三渎乱之时，不待告命，可以变化裁制，以行有为之道。</p><p>无为之道，养真蒙也；有为之道，化假蒙也。养真化假，有为无为，随时而用，不失其正。或自有为而归无为，或自无为而成有为，总以至善无恶，浑然天理，还元返本，归于童蒙为极功。行蒙道者，可不以正哉!</p><p>初六，在蒙之初，人心方起，急须严加克制，如利用刑人也。若姑息养奸，纵性为恶，如用说桎梏以往，渐入于下愚不移之地，而莫可救止，取吝必矣。此贵防阴于蒙之初也。</p><p>九二，刚而能柔，借阴养阳，是包蒙也。蒙在包中，外暗内明，不但阳气不伤，而且阳气增长，如纳妇之吉，而子自克家。此能养阳于蒙之时也。</p><p>六三，阴柔不中不正，恣情纵欲，故勿用取女。勿用者，以其人心用事，贪财好色，如淫奔之女，见金夫不有躬，未得于人，早失其己，其无所利，可知此蒙，而又滋其蒙也。</p><p>六四，性质本愚，又与小人为伍，不知亲近高明之士，以扩充其识见，终困于蒙而不得出，岂只取吝而已乎?此蒙而不知其蒙也。</p><p>六五，于止知其所止，以无能而顺有能，借刚济柔，虽蒙不蒙，正童蒙，不识不知，顺帝之则之吉道。此蒙而自知其蒙也。</p><p>上九，刚而居于蒙之极，是能惩忿窒欲，猛力以退客气，如击蒙也。</p><p>退阴之道，不利于人心而为寇，利于道心而御寇。去人心，振道心，阴气退尽，阳气纯全，复见本来面目，此蒙而终不能蒙也。</p><p>观于六爻之蒙，真假大别，真者用而假者去，养之退之，皆能不失其正，阴符之道尽矣。</p>',27)])])}const m=a(s,[["render",n]]);export{d as __pageData,m as default};
